            @if($plans->isEmpty())
                <div class="empty">در حال حاضر پلن فعالی برای نمایش وجود ندارد. لطفاً بعداً دوباره سر بزنید.</div>
            @else
                <div class="plans">
                    @foreach($plans as $plan)
                        @php
                            $effectivePrice = (int) $plan->effectivePrice();
                            $hasDiscount = $plan->discountIsActive() && (int) $plan->price > $effectivePrice;
                            $discountPercent = $hasDiscount ? (int) round((1 - $effectivePrice / max(1, (int) $plan->price)) * 100) : 0;
                            $priceLabel = $effectivePrice <= 0 ? 'رایگان' : number_format($effectivePrice).' <small>تومان</small>';
                        @endphp
                        <article class="plan">
                            @if($effectivePrice <= 0)<span class="plan-badge">شروع رایگان</span>@elseif($hasDiscount)<span class="plan-badge">تخفیف ویژه · {{ $discountPercent }}٪</span>@else<span class="plan-badge">اشتراک رسمی صابخونه</span>@endif
                            <div class="plan-icon" aria-hidden="true">{{ $loop->first ? '✦' : ($loop->iteration === 2 ? '⌂' : '◆') }}</div>
                            <h3>{{ $plan->name }}</h3>
                            <p class="desc">مدیریت ساختمان و پیگیری امور روزمره در یک فضای یکپارچه</p>
                            <div class="price">{!! $priceLabel !!}</div>
                            <div class="discount">@if($hasDiscount)قیمت اصلی: <del>{{ number_format((int) $plan->price) }} تومان</del>@elseif((int) $plan->duration_months > 1 && $effectivePrice > 0)برای {{ $plan->duration_months }} ماه اشتراک@endif</div>
                            <ul class="features">
                                <li><span class="check">✓</span><span>ظرفیت تا {{ number_format((int) $plan->units_limit) }} واحد</span></li>
                                <li><span class="check">✓</span><span>{{ number_format((int) $plan->duration_months) }} ماه اعتبار</span></li>
                                <li><span class="check">✓</span><span>مدیریت ساکنان، شارژ و درخواست‌ها</span></li>
                                <li><span class="check">✓</span><span>دسترسی از طریق پنل صابخونه</span></li>
                            </ul>
                            @auth
                                <a class="btn primary" href="{{ route('subscription.show') }}">مشاهده اشتراک‌ها <span aria-hidden="true">←</span></a>
